#include <vector>
#include <algorithm>

class Solution {
public:
    int maximalPathQuality(std::vector<int>& values, std::vector<std::vector<int>>& edges, int maxTime) {
        int n = values.size();
        std::vector<std::vector<std::pair<int, int>>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back({e[1], e[2]});
            adj[e[1]].push_back({e[0], e[2]});
        }

        std::vector<int> visited(n, 0);
        int maxQuality = 0;

        auto dfs = [&](auto& self, int node, int curTime, int curQuality) -> void {
            if (visited[node] == 0) curQuality += values[node];
            visited[node]++;

            if (node == 0) {
                maxQuality = std::max(maxQuality, curQuality);
            }

            for (auto [nxt, t] : adj[node]) {
                if (curTime + t <= maxTime) {
                    self(self, nxt, curTime + t, curQuality);
                }
            }

            visited[node]--;
        };

        dfs(dfs, 0, 0, 0);
        return maxQuality;
    }
};

import java.util.ArrayList;
import java.util.List;

class Solution {
    private int maxQuality = 0;

    public int maximalPathQuality(int[] values, int[][] edges, int maxTime) {
        int n = values.length;
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) {
            adj.get(e[0]).add(new int[]{e[1], e[2]});
            adj.get(e[1]).add(new int[]{e[0], e[2]});
        }

        int[] visited = new int[n];
        dfs(0, 0, 0, values, adj, visited, maxTime);
        return maxQuality;
    }

    private void dfs(int node, int curTime, int curQuality, int[] values, List<List<int[]>> adj, int[] visited, int maxTime) {
        if (visited[node] == 0) curQuality += values[node];
        visited[node]++;

        if (node == 0) {
            maxQuality = Math.max(maxQuality, curQuality);
        }

        for (int[] edge : adj.get(node)) {
            int nxt = edge[0];
            int t = edge[1];
            if (curTime + t <= maxTime) {
                dfs(nxt, curTime + t, curQuality, values, adj, visited, maxTime);
            }
        }

        visited[node]--;
    }
}

/**
 * @param {number[]} values
 * @param {number[][]} edges
 * @param {number} maxTime
 * @return {number}
 */
var maximalPathQuality = function(values, edges, maxTime) {
    const n = values.length;
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v, t] of edges) {
        adj[u].push([v, t]);
        adj[v].push([u, t]);
    }

    const visited = new Int32Array(n);
    let maxQuality = 0;

    function dfs(node, curTime, curQuality) {
        if (visited[node] === 0) curQuality += values[node];
        visited[node]++;

        if (node === 0) {
            if (curQuality > maxQuality) maxQuality = curQuality;
        }

        for (const [nxt, t] of adj[node]) {
            if (curTime + t <= maxTime) {
                dfs(nxt, curTime + t, curQuality);
            }
        }

        visited[node]--;
    }

    dfs(0, 0, 0);
    return maxQuality;
};
